FIXUPS=(('catalog', 4486, 0), ('owner', 4533, 0), ('prepare', 4666, 0), ('tools', 4694, 0), ('execute', 4722, 0), ('publish', 4750, 0), ('transport', 4778, 0), ('diagnostics', 4806, 0), ('cleanup', 4834, 0), ('location', 4862, 0), ('hash', 5008, 0), ('admission', 5015, 0), ('canonical', 5022, 0), ('llvm', 5029, 0), ('llvm_meta', 5036, 0), ('which', 5043, 0), ('path', 5050, 0), ('file', 5057, 0), ('capture', 5064, 0), ('object', 5071, 0), ('shared', 5078, 0), ('identity', 5085, 0), ('rmtree', 5092, 0), ('receipt', 5099, 0), ('buffers', 5106, 0), ('catalog', 6054, 0), ('log_origin_owner', 6101, 0), ('error_prepare', 6269, 0), ('tools', 6297, 0), ('error_execute', 6325, 0), ('publish', 6353, 0), ('error_transport', 6381, 0), ('diagnostics', 6409, 0), ('error_cleanup_origin', 6437, 0), ('origin_location', 6465, 0), ('hash', 6818, 0), ('admission', 6828, 0), ('canonical', 6838, 0), ('llvm', 6848, 0), ('llvm_meta', 6858, 0), ('which', 6868, 0), ('path', 6878, 0), ('file', 6888, 0), ('error_capture', 6898, 0), ('object', 6908, 0), ('shared', 6918, 0), ('error_identity', 6928, 0), ('rmtree', 6938, 0), ('receipt', 6948, 0), ('origin_buffers', 6958, 0), ('value_owner', 1311, 0), ('value_coercion', 1492, 0), ('value_transport', 1520, 0), ('value_cleanup', 1548, 0), ('value_buffers', 2117, 0), ('fs_codec', 2107, 0), ('value_exceptions', 1576, 0), ('value_path', 1604, 0), ('which', 2340, 0), ('value_windows', 2127, 0), ('error_surface', 1632, 0), ('error_builder', 1660, 0), ('string_repr', 2157, 0), ('error_capture_value', 1688, 0), ('utf8_error', 2137, 0), ('error_secondary', 1716, 0), ('value_early_error', 3392, 0), ('error_inventory', 1828, 0), ('inventory_text', 2147, 0), ('error_fileflow', 1800, 0), ('error_cleanup_value', 1772, 0), ('log_hooks', 6493, 0), ('log_failure', 6521, 0), ('log_retire', 6549, 0), ('log_codec', 6968, 0), ('log_owner', 6978, 0), ('log_cwd', 6988, 0), ('string_repr', 6998, 0), ('log_binding', 1744, 0), ('log_owner', 2061, 0), ('log_owner', 2037, 7), ('reap_text', 2013, 0))
RELOCATIONS=()
DYNAMIC_RELOCATIONS=(('@bridge',2232,'dlsym'),('@bridge',5230,'dlsym'),('which',776,'dlsym'),('capture',1010,'dlsym'),('error_capture',1010,'dlsym'))
ENTRY_OFFSETS={'capture':64,'path':64,'error_capture':64}
LENGTH_FIXUPS=(('catalog', 4499), ('catalog', 6067))
IMPORTS=('dlsym',)
EXPORT='hia_clang_value_compile'
EXTRA_EXPORTS=(('hia_clang_value_bind_owner','@owner_bind'),('hia_clang_value_bind','@bind'),('hia_clang_value_exception','@exception'),('hia_clang_compile','@legacy'),('hia_program_llvm','llvm'),('hia_program_llvm_metadata','llvm_meta'))
BRIDGE_EXPORTS={'@owner_bind': (3401, 519), '@bind': (8, 3912), '@exception': (13, 3907), '@legacy': (3920, 1553)}
EXPORT_SIZE=3920
MAGIC=int.from_bytes(b'HIACVEP1','little')
def fixed_parts():
 strings=b'\0'+EXPORT.encode()+b'\0'+b''.join(name.encode()+b'\0'for name,role in EXTRA_EXPORTS)+b''.join(x.encode()+b'\0'for x in IMPORTS)
 symbols=b''.join([bytes(24),struct.pack('<IBBHQQ',0,3,0,1,0,0),struct.pack('<IBBHQQ',1,18,0,1,0,EXPORT_SIZE)]+[struct.pack('<IBBHQQ',strings.index(name.encode()+b'\0'),18,0,1,*BRIDGE_EXPORTS.get(role,(0,0)))for name,role in EXTRA_EXPORTS]+[struct.pack('<IBBHQQ',strings.index(name.encode()+b'\0'),16,0,0,0,0)for name in IMPORTS])
 relas=b''.join(struct.pack('<QQq',0,((3+len(EXTRA_EXPORTS)+IMPORTS.index(name))<<32)|4,-4)for role,offset,name in DYNAMIC_RELOCATIONS)
 header=struct.pack('<16sHHIQQQIHHHHHH',b'\x7fELF\x02\x01\x01'+bytes(9),1,62,1,0,0,0,0,64,0,0,64,7,5)
 rows=[bytes(64)]
 for name,kind,flags,size,link,info,align,extent in [('.text',1,6,0,0,0,16,0),('.rela.text',4,0,len(relas),3,1,8,24),('.symtab',2,0,len(symbols),4,2,8,24),('.strtab',3,0,len(strings),0,0,1,0),('.shstrtab',3,0,len(base.SECTIONS),0,0,1,0),('.note.GNU-stack',1,0,0,0,0,1,0)]:
  rows.append(struct.pack('<IIQQQQIIQQ',base.SECTIONS.index(name.encode()+b'\0'),kind,flags,0,0,size,link,info,align,extent))
 return header+BRIDGE,relas,symbols,strings,b''.join(rows)
def reference_object(parts):
 if len(parts)!=len(ROLES)or any(not x or len(x)>4194304 for x in parts):raise ValueError('actual bounded HIA role count')
 prefix,relas,symbols,strings,sections=fixed_parts();raw=bytearray(prefix);offsets={}
 for role,part in zip(ROLES,parts):
  raw.extend(bytes((-len(raw))%16));offsets[role]=len(raw);raw.extend(part)
 for role,hole,delta in FIXUPS:
  assert raw[64+hole:68+hole]==bytes(4)
  struct.pack_into('<i',raw,64+hole,offsets[role]+ENTRY_OFFSETS.get(role,0)+delta-64-hole-4)
 for role,hole in LENGTH_FIXUPS:struct.pack_into('<Q',raw,64+hole,len(parts[ROLES.index(role)]))
 if len(raw)-64>16777216:raise ValueError('original text limit')
 textsize=len(raw)-64;raw.extend(bytes((-len(raw))%8));tail=[]
 for data in [relas,symbols,strings,base.SECTIONS]:tail.append(len(raw));raw.extend(data)
 tail.append(len(raw));raw.extend(bytes((-len(raw))%8));sh=len(raw);raw.extend(sections)
 for i,(role,at,name)in enumerate(DYNAMIC_RELOCATIONS):struct.pack_into('<Q',raw,tail[0]+i*24,at if role=='@bridge'else offsets[role]-64+at)
 for index,(name,role)in enumerate(EXTRA_EXPORTS,3):
  if role not in BRIDGE_EXPORTS:struct.pack_into('<QQ',raw,tail[1]+index*24+8,offsets[role]-64,len(parts[ROLES.index(role)]))
 struct.pack_into('<Q',raw,40,sh);struct.pack_into('<QQ',raw,sh+88,64,textsize)
 for i,at in enumerate(tail,2):struct.pack_into('<Q',raw,sh+i*64+24,at)
 return bytes(raw)
def reference_flat(parts):
 raw=reference_object(parts);sh=struct.unpack_from('<Q',raw,40)[0];n=struct.unpack_from('<Q',raw,sh+96)[0];return raw[64:64+n]
def source_program():
 prefix,relas,symbols,strings,sections=fixed_parts();calls={};functions=[]
 for name,raw in [('prefix',prefix[:64]),('tail',relas+symbols+strings+base.SECTIONS),('sections',sections),('flat_prefix',BRIDGE)]:
  calls[name],source=base.emitters(name,raw);functions.append(source)
 count=len(ROLES);header=(count+3)*8;mode_at=16+count*8;T=16*count
 src=f'''def pack(s:readbuf,o:mutbuf,w:mutbuf) -> u32:
    if length(w)<{T+64}:
        return 4294967294
    if length(s)<{header} or uint(s,0,8)!={MAGIC} or uint(s,8,8)!={count} or uint(s,{mode_at},8)>1:
        return 4294967295
    total={header}
    i=0
    while i<{count}:
        n=uint(s,16+i*8,8)
        if n==0 or n>4194304:
            return 4294967295
        write(w,i*8,n,8)
        total=total+n
        i=i+1
    if length(s)!=total:
        return 4294967295
    layout(w)
    if get(w,{T})-64>16777216:
        return 4294967295
    if uint(s,{mode_at},8)==1:
        return flat(s,o,w)
    n=get(w,{T+56})
    if length(o)<n:
        return 4294967294
    i=0
    while i<n:
        store(o,i,0)
        i=i+1
'''
 for key,at in [('prefix','0'),('flat_prefix','64'),('tail',f'get(w,{T+8})'),('sections',f'get(w,{T+48})')]:
  for fn in calls[key]:src+=f'    {fn}(o,{at})\n'
 src+=f'''    sections=get(w,{T+48})
    write(o,40,sections,8)
    write(o,sections+88,64,8)
    write(o,sections+96,get(w,{T})-64,8)
'''
 for i in range(2,7):src+=f'    write(o,sections+{64*i+24},get(w,{T+8*(i-1)}),8)\n'
 for index,(name,role)in enumerate(EXTRA_EXPORTS,3):
  if role in BRIDGE_EXPORTS:continue
  src+=f'    write(o,get(w,{T+16})+{index*24+8},get(w,{count*8+8*ROLES.index(role)})-64,8)\n'
  src+=f'    write(o,get(w,{T+16})+{index*24+16},get(w,{8*ROLES.index(role)}),8)\n'
 for role,hole,delta in FIXUPS:src+=f'    write(o,{64+hole},get(w,{count*8+8*ROLES.index(role)})+{ENTRY_OFFSETS.get(role,0)+delta}-{64+hole+4},4)\n'
 for role,hole in LENGTH_FIXUPS:src+=f'    write(o,{64+hole},get(w,{8*ROLES.index(role)}),8)\n'
 for i,(role,at,name)in enumerate(DYNAMIC_RELOCATIONS):
  value=str(at)if role=='@bridge'else f'get(w,{count*8+8*ROLES.index(role)})-64+{at}'
  src+=f'    write(o,get(w,{T+8})+{i*24},{value},8)\n'
 src+=f'''    at={header}
    i=0
    while i<{count}:
        copy(s,o,at,get(w,{count*8}+i*8),get(w,i*8))
        at=at+get(w,i*8)
        i=i+1
    return get(w,{T+56})

def layout(w:mutbuf) -> u64:
    at=({len(prefix)}+15)&18446744073709551600
    i=0
    while i<{count}:
        write(w,{count*8}+i*8,at,8)
        at=at+get(w,i*8)
        if i!={count-1}:
            at=(at+15)&18446744073709551600
        i=i+1
    write(w,{T},at,8)
    at=(at+7)&18446744073709551608
    write(w,{T+8},at,8)
    at=at+{len(relas)}
    write(w,{T+16},at,8)
    at=at+{len(symbols)}
    write(w,{T+24},at,8)
    at=at+{len(strings)}
    write(w,{T+32},at,8)
    at=at+{len(base.SECTIONS)}
    write(w,{T+40},at,8)
    at=(at+7)&18446744073709551608
    write(w,{T+48},at,8)
    write(w,{T+56},at+448,8)
    return 0

def flat(s:readbuf,o:mutbuf,w:mutbuf) -> u32:
    n=get(w,{T})-64
    if length(o)<n:
        return 4294967294
    i=0
    while i<n:
        store(o,i,0)
        i=i+1
'''
 for fn in calls['flat_prefix']:src+=f'    {fn}(o,0)\n'
 for role,hole,delta in FIXUPS:src+=f'    write(o,{hole},get(w,{count*8+8*ROLES.index(role)})+{ENTRY_OFFSETS.get(role,0)+delta}-{64+hole+4},4)\n'
 for role,hole in LENGTH_FIXUPS:src+=f'    write(o,{hole},get(w,{8*ROLES.index(role)}),8)\n'
 src+=f'''    at={header}
    i=0
    while i<{count}:
        copy(s,o,at,get(w,{count*8}+i*8)-64,get(w,i*8))
        at=at+get(w,i*8)
        i=i+1
    return n

def get(w:mutbuf,at:u64) -> u64:
    value=0
    i=0
    while i<8:
        value=value|(byte(w,at+i)<<(8*i))
        i=i+1
    return value
'''
 return src+'\n'+'\n'.join(functions)+base.HELPERS
def main():
 t=document(source_program(),'clang_value_error_packer');p=ROOT/'examples/hia_bootstrap/clang_value_error_packer.hepta';p.write_text(render_assembly(t));print(p.name,p.stat().st_size,flush=True)
